 import unittest
from candidate import rolling_max

class TestRollingMax(unittest.TestCase):
    def test_rolling_max_normalcase(self):
        self.assertEqual(rolling_max([1, 2, 3, 2, 3, 4, 2]), [1, 2, 3, 3, 3, 4, 4])

    def test_rolling_max_empty_list(self):
        self.assertEqual(rolling_max([]), [])

    def test_rolling_max_single_element(self):
        self.assertEqual(rolling_max([1]), [1])

    def test_rolling_max_multiple_maxima(self):
        self.assertEqual(rolling_max([3, 2, 3, 4, 2, 2, 3]), [3, 3, 4, 4, 4, 4, 4])

    def test_rolling_max_all_same(self):
        self.assertEqual(rolling_max([5, 5, 5]), [5, 5, 5])

    def test_rolling_max_negative_numbers(self):
        self.assertEqual(rolling_max([-2, -3, -2, -3, -4]), [-2, -3, -3, -3, -4])

    def test_rolling_max_mixed_numbers(self):
        self.assertEqual(rolling_max([-2, 3, -3, 4, -2]), [-2, 3, 3, 4, 4])

    def test_rolling_max_with_floats(self):
        self.assertAlmostEqual(rolling_max([2.5, 3.5, 1.2, 4.3]), [2.5, 3.5, 3.5, 4.3])

    def test_rolling_max_none_value(self):
        self.assertRaises(TypeError, rolling_max, None)

    def test_rolling_max_list_of_strings(self):
        self.assertRaises(TypeError, rolling_max, ["a", "b", "c"])

if __name__ == '__main__':
    unittest.main()
